import java.io.IOException;
public final class ReadingFormatException extends IOException {
    private static final long serialVersionUID = 1L;
    private final int lineNumber;
    public ReadingFormatException(int lineNumber) {
        super("Invalid reading at line " + lineNumber);
        this.lineNumber = lineNumber;
    }
    public int lineNumber() { return lineNumber; }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class ReadingExport {
    private ReadingExport() {}
    public static List<Reading> parse(Reader reader) throws IOException {
        BufferedReader buffered = reader instanceof BufferedReader ? (BufferedReader) reader : new BufferedReader(reader);
        List<Reading> readings = new ArrayList<>();
        String line;
        int number = 0;
        while ((line = buffered.readLine()) != null) {
            number++;
            String[] fields = line.split(java.util.regex.Pattern.quote("|"), -1);
            if (fields.length != 2 || !fields[0].matches("[a-z]{1,8}")) throw new ReadingFormatException(number);
            try {
                int value = Integer.parseInt(fields[1]);
                if (!Integer.toString(value).equals(fields[1]) || value < -50 || value > 150) throw new NumberFormatException();
                readings.add(new Reading(fields[0], value));
            } catch (NumberFormatException error) { throw new ReadingFormatException(number); }
        }
        return readings;
    }
    public static void convert(Path input, Path output) throws IOException {
        List<Reading> readings;
        try (BufferedReader reader = Files.newBufferedReader(input, StandardCharsets.UTF_8)) { readings = parse(reader); }
        try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8)) {
            for (Reading reading : readings) {
                writer.write(reading.channel().toUpperCase(Locale.ROOT) + ":" + reading.value() + "\n");
            }
        }
    }
}
